export function formatRunTime(ms: number): string {
  const tenths = Math.floor(Math.max(0, ms) / 100)
  return `${Math.floor(tenths / 600)}:${String(Math.floor(tenths / 10) % 60).padStart(2, '0')}.${tenths % 10}`
}

export function Metric(props: { label: string; value: string; accent: Color4 }) {
  const theme = sceneUiTheme()
  return <UiEntity uiTransform={{ width: '100%', height: 72, flexDirection: 'column', pointerFilter: 'none' }}>
    <UiText value={props.label} color={theme.muted} size={16} height={24} />
    <UiText value={props.value} color={props.accent} size={32} height={44} mono />
  </UiEntity>
}

export function ProgressBar(props: { value: number; maximum: number; accent: Color4 }) {
  const percent = props.maximum > 0 ? Math.min(100, Math.max(0, props.value / props.maximum * 100)) : 0
  return <UiEntity uiTransform={{ width: '100%', height: 6, borderRadius: 3, pointerFilter: 'none' }} uiBackground={{ color: sceneUiTheme().hover }}>
    <UiEntity uiTransform={{ width: `${percent}%`, height: '100%', borderRadius: 3, pointerFilter: 'none' }} uiBackground={{ color: props.accent }} />
  </UiEntity>
}

function Progress(props: { label: string; value: number; maximum: number; theme: UiTheme }) {
  if (props.maximum === 0) return null
  return <UiEntity uiTransform={{ width: '100%', height: 56, flexDirection: 'column', pointerFilter: 'none' }}>
    <UiEntity uiTransform={{ width: '100%', height: 34, pointerFilter: 'none' }}>
      <UiText value={props.label} color={props.theme.muted} size={18} uiTransform={{ width: '65%' }} />
      <UiText value={`${props.value} / ${props.maximum}`} color={props.theme.text} size={18} align="middle-right" mono uiTransform={{ width: '35%' }} />
    </UiEntity>
    <ProgressPips value={props.value} maximum={props.maximum} theme={props.theme} />
  </UiEntity>
}

export interface RunHudProps {
  title: string
  objective: string
  elapsedMs: number
  bestMs: number | null
  phase: 'ready' | 'running' | 'finished'
  checkpoint: number
  checkpoints: number
  collected: number
  collectibles: number
  health: number | null
  maxHealth: number
  respawnSeconds: number
  notice: string
  accentColor: string
  restart(): void
  /** "Big timer" replaces the run panel and corner clock with one large clock at the top centre. */
  hud?: 'Full' | 'Big timer'
}

function runGoals(props: RunHudProps): string {
  const goals: string[] = []
  if (props.checkpoints > 0) goals.push(`Checkpoint ${props.checkpoint} / ${props.checkpoints}`)
  if (props.collectibles > 0) goals.push(`${props.collected} / ${props.collectibles} collected`)
  return goals.join('  ·  ')
}

function RunPanel(props: { run: RunHudProps; theme: UiTheme }) {
  const { run, theme } = props
  return <UiPanel theme={theme} uiTransform={{ width: HUD_COLUMN_WIDTH, height: 252, padding: 20 }}>
    <UiText value={run.phase === 'ready' ? 'READY TO RUN' : 'RUN IN PROGRESS'} color={theme.accentText} size={16} height={24} />
    <UiText value={run.title} color={theme.text} size={24} height={36} />
    <UiText value={run.phase === 'ready' ? 'Cross the start to begin' : run.objective} color={theme.muted} size={18} height={52} />
    <Progress label="Collected" value={run.collected} maximum={run.collectibles} theme={theme} />
    <Progress label="Checkpoint" value={run.checkpoint} maximum={run.checkpoints} theme={theme} />
  </UiPanel>
}

function LifePanel(props: { run: RunHudProps; theme: UiTheme; hint: boolean }) {
  const { run, theme } = props
  const lifeLine = run.health !== null || run.respawnSeconds > 0
  return <UiPanel theme={theme} uiTransform={{ width: HUD_COLUMN_WIDTH, height: (lifeLine ? 44 : 0) + (props.hint ? 32 : 0) + 32, padding: 16 }}>
    {lifeLine && <UiEntity uiTransform={{ width: '100%', height: 44, flexDirection: 'column', pointerFilter: 'none' }}>
      <UiText value={run.respawnSeconds > 0 ? `Respawning in ${Math.ceil(run.respawnSeconds)}…` : `Health ${run.health} / ${run.maxHealth}`} color={run.respawnSeconds > 0 ? theme.danger : theme.text} size={16} height={30} />
      {run.health !== null && <ProgressBar value={run.health} maximum={run.maxHealth} accent={run.health <= run.maxHealth * 0.25 ? theme.danger : theme.accent} />}
    </UiEntity>}
    {props.hint && <UiText value={controlsHint()} color={theme.muted} size={16} height={32} />}
  </UiPanel>
}

function BigTimer(props: { run: RunHudProps; theme: UiTheme }) {
  const { run, theme } = props
  const goals = runGoals(run)
  return <UiPanel theme={theme} uiTransform={{ width: HUD_COLUMN_WIDTH, height: goals === '' ? 120 : 152, padding: 16 }}>
    <UiText value={formatRunTime(run.elapsedMs)} color={theme.text} size={64} height={88} align="middle-center" mono />
    {goals !== '' && <UiText value={goals} color={theme.muted} size={16} height={28} align="middle-center" />}
  </UiPanel>
}

function Completion(props: { run: RunHudProps; theme: UiTheme }) {
  const { run, theme } = props
  const stats = (run.collectibles > 0 ? 1 : 0) + (run.checkpoints > 0 ? 1 : 0)
  return <UiEntity uiTransform={{ width: '100%', height: '100%', alignItems: 'center', justifyContent: 'center', pointerFilter: 'none' }}
    uiBackground={{ color: { r: 0, g: 0, b: 0, a: 0.28 } }}>
    <UiPanel theme={theme} uiTransform={{ width: 520, maxWidth: '90%', height: stats === 0 ? 312 : 420, padding: 28 }}>
      <UiText value="RUN COMPLETE" color={theme.accentText} size={16} height={28} align="middle-center" />
      <UiText value={run.title} color={theme.text} size={28} height={44} align="middle-center" />
      <UiText value={formatRunTime(run.elapsedMs)} color={theme.text} size={64} height={88} align="middle-center" mono />
      <UiText value={run.bestMs === null ? 'Confirming your result…' : `Personal best  ${formatRunTime(run.bestMs)}`} color={theme.muted} size={18} height={36} align="middle-center" />
      {stats > 0 && <UiEntity uiTransform={{ width: '100%', height: 92, margin: { top: 8, bottom: 16 }, padding: 16, borderRadius: 8, pointerFilter: 'none' }} uiBackground={{ color: theme.surface }}>
        {run.collectibles > 0 && <UiEntity uiTransform={{ width: `${100 / stats}%`, height: 60, flexDirection: 'column', pointerFilter: 'none' }}>
          <UiText value="COLLECTED" color={theme.muted} size={16} height={24} align="middle-center" />
          <UiText value={`${run.collected} / ${run.collectibles}`} color={theme.accentText} size={26} height={36} align="middle-center" mono />
        </UiEntity>}
        {run.checkpoints > 0 && <UiEntity uiTransform={{ width: `${100 / stats}%`, height: 60, flexDirection: 'column', pointerFilter: 'none' }}>
          <UiText value="CHECKPOINT" color={theme.muted} size={16} height={24} align="middle-center" />
          <UiText value={`${run.checkpoint} / ${run.checkpoints}`} color={theme.accentText} size={26} height={36} align="middle-center" mono />
        </UiEntity>}
      </UiEntity>}
      <UiButton theme={theme} label="Run again" onClick={run.restart} />
    </UiPanel>
  </UiEntity>
}

/** Places the run HUD in the shared layout: the run panel and health on the left, the clock and Restart top right,
 *  the big timer and notices top centre, and the completion screen as a modal. Returns its removal. */
export function mountRunHud(read: () => RunHudProps): () => void {
  let run = read()
  const refresh = () => { run = read() }
  engine.addSystem(refresh)
  const theme = () => sceneUiTheme(run.accentColor)
  const playing = () => run.phase !== 'finished'
  const full = () => run.hud !== 'Big timer'
  const removals = [
    addHudItem('left', () => playing() && full() ? <RunPanel run={run} theme={theme()} /> : null, { order: -100 }),
    addHudItem('left', () => playing() && (full() || run.health !== null || run.respawnSeconds > 0)
      ? <LifePanel run={run} theme={theme()} hint={full()} /> : null, { order: -90 }),
    addHudItem('top', () => playing() && !full() ? <BigTimer run={run} theme={theme()} /> : null, { order: -100 }),
    addHudItem('right', () => playing() && full() ? <UiPanel theme={theme()} uiTransform={{ width: 208, height: 120 }}>
      <Metric label="TIME" value={formatRunTime(run.elapsedMs)} accent={theme().text} />
    </UiPanel> : null, { order: -100 }),
    addHudItem('right', () => playing() ? <UiButton theme={theme()} label="Restart run" secondary onClick={run.restart}
      uiTransform={{ width: 172 }} /> : null, { order: -90 }),
    addHudItem('top', () => playing() && run.notice !== '' ? <UiNotice theme={theme()} text={run.notice} uiTransform={{ width: 520, maxWidth: '100%' }} /> : null, { order: 40 }),
    addHudItem('modal', () => playing() ? null : <Completion run={run} theme={theme()} />, { open: () => !playing() })
  ]
  return () => {
    engine.removeSystem(refresh)
    for (const remove of removals) remove()
  }
}
